import json
r=json.load(open('/tmp/r001_contract.json'))
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k not in ('context','study_schema','candidate_api'):
  print(k,json.dumps(v,indent=2))
c=r['context']; print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ('history','knowledge'):
  print(k,json.dumps(v,indent=2))
print('HISTORY SUMMARY')
for h in c['history']:
 print(json.dumps({k:v for k,v in h.items() if k not in ('validation','candidate_diagnostics')},ensure_ascii=False))
 print('METRICS',json.dumps(h.get('validation',{}),ensure_ascii=False))
PY"

